(2,'FASTConsentSubscriptionTopic',1,'SubscriptionTopic','valid','system','2026-09-10 10:25:13','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\n<Basic xmlns=\"http://hl7.org/fhir\">\n  <id value=\"FASTConsentSubscriptionTopic\"/>\n  <meta>\n    <versionId value=\"1\"/>\n    <lastUpdated value=\"2026-09-10T10:25:13.211-04:00\"/>\n  </meta>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.url\">\n    <valueUri value=\"http://hl7.org/fhir/us/consent-management/SubscriptionTopic/FASTConsentSubscriptionTopic\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.version\">\n    <valueString value=\"1.0.0-preview\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.name\">\n    <valueString value=\"FASTConsent\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.title\">\n    <valueString value=\"FAST Consent Subscription Topic\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.status\">\n    <valueCode value=\"active\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.experimental\">\n    <valueBoolean value=\"false\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.date\">\n    <valueDateTime value=\"2025-03-01\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.publisher\">\n    <valueString value=\"HL7 International / Community Based Collaborative Care\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.contact\">\n    <valueContactDetail>\n      <name value=\"HL7 International / Community Based Collaborative Care\"/>\n      <telecom>\n        <system value=\"url\"/>\n        <value value=\"http://www.hl7.org/Special/committees/homehealth\"/>\n      </telecom>\n    </valueContactDetail>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.description\">\n    <valueMarkdown value=\"This is the subscription topic used for ensuring Consent records are updated amongst a set of Consent Registries.\"/>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.jurisdiction\">\n    <valueCodeableConcept>\n      <coding>\n        <system value=\"urn:iso:std:iso:3166\"/>\n        <code value=\"US\"/>\n        <display value=\"United States of America\"/>\n      </coding>\n    </valueCodeableConcept>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.resourceTrigger\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"When a consent record has been \'touched\' and needs to be distributed amongst interested parties.\"/>\n    </extension>\n    <extension url=\"resource\">\n      <valueUri value=\"http://hl7.org/fhir/StructureDefinition/Consent\"/>\n    </extension>\n    <extension url=\"supportedInteraction\">\n      <valueCode value=\"create\"/>\n    </extension>\n    <extension url=\"supportedInteraction\">\n      <valueCode value=\"update\"/>\n    </extension>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.canFilterBy\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"The patient whose consent is being subscribed to. Use patient:identifier chained search to filter by patient identifier.\"/>\n    </extension>\n    <extension url=\"filterParameter\">\n      <valueString value=\"patient\"/>\n    </extension>\n    <extension url=\"filterDefinition\">\n      <valueUri value=\"http://hl7.org/fhir/SearchParameter/clinical-patient\"/>\n    </extension>\n    <extension url=\"comparator\">\n      <valueCode value=\"eq\"/>\n    </extension>\n    <extension url=\"modifier\">\n      <valueCode value=\"identifier\"/>\n    </extension>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.canFilterBy\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"The controller of the consent. Use controller:identifier chained search to filter by organization identifier.\"/>\n    </extension>\n    <extension url=\"filterParameter\">\n      <valueString value=\"controller\"/>\n    </extension>\n    <extension url=\"filterDefinition\">\n      <valueUri value=\"http://hl7.org/fhir/us/consent-management/SearchParameter/fast-consent-controller\"/>\n    </extension>\n    <extension url=\"comparator\">\n      <valueCode value=\"eq\"/>\n    </extension>\n    <extension url=\"modifier\">\n      <valueCode value=\"identifier\"/>\n    </extension>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.canFilterBy\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"The identifier of one of the actors that is controlled by a consent.\"/>\n    </extension>\n    <extension url=\"filterParameter\">\n      <valueString value=\"actor\"/>\n    </extension>\n    <extension url=\"filterDefinition\">\n      <valueUri value=\"http://hl7.org/fhir/SearchParameter/Consent-actor\"/>\n    </extension>\n    <extension url=\"comparator\">\n      <valueCode value=\"eq\"/>\n    </extension>\n    <extension url=\"modifier\">\n      <valueCode value=\"identifier\"/>\n    </extension>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.canFilterBy\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"The status of a consent.\"/>\n    </extension>\n    <extension url=\"filterParameter\">\n      <valueString value=\"status\"/>\n    </extension>\n    <extension url=\"filterDefinition\">\n      <valueUri value=\"http://hl7.org/fhir/SearchParameter/Consent-status\"/>\n    </extension>\n    <extension url=\"comparator\">\n      <valueCode value=\"eq\"/>\n    </extension>\n  </extension>\n  <extension url=\"http://hl7.org/fhir/5.0/StructureDefinition/extension-SubscriptionTopic.canFilterBy\">\n    <extension url=\"description\">\n      <valueMarkdown value=\"The category of the consent.\"/>\n    </extension>\n    <extension url=\"filterParameter\">\n      <valueString value=\"category\"/>\n    </extension>\n    <extension url=\"filterDefinition\">\n      <valueUri value=\"http://hl7.org/fhir/SearchParameter/Consent-category\"/>\n    </extension>\n    <extension url=\"comparator\">\n      <valueCode value=\"eq\"/>\n    </extension>\n  </extension>\n  <code>\n    <coding>\n      <system value=\"http://hl7.org/fhir/fhir-types\"/>\n      <code value=\"SubscriptionTopic\"/>\n    </coding>\n  </code>\n</Basic>');
